select count(l1_0.id) from listing l1_0 left join category c1_0 on c1_0.id=l1_0.category_id where l1_0.deleted_at is null and l1_0.status='ON_SALE' and l1_0.moderation_status in ('NORMAL','WARNING_ACK_REQUIRED') and (lower(l1_0.title) like '%iphone%' escape '' or lower(c1_0.name) like '%iphone%' escape '' or lower(c1_0.manufacturer) like '%iphone%' escape '') and 1=1 and 1=1 and 1=1 and 1=1 and 1=1 and 1=1 and (select count(lci1_0.id) from listing_checklist_item lci1_0 where lci1_0.listing_id=l1_0.id and lci1_0.is_required and lci1_0.completion_status='COMPLETED') between 1 and 4;
